def choose_move(observation):
    grid_w = observation.get("grid_width", 0)
    grid_h = observation.get("grid_height", 0)
    self_pos = observation.get("self_position", {"x":0,"y":0})
    opp_pos = observation.get("opponent_position", {"x":0,"y":0})
    x = int(self_pos.get("x", 0))
    y = int(self_pos.get("y", 0))

    # Simple deterministic priority:
    # 1) Move away from opponent if adjacent or same
    ox = int(opp_pos.get("x", 0))
    oy = int(opp_pos.get("y", 0))
    dx = 0
    dy = 0
    if abs(ox - x) <= 1 and abs(oy - y) <= 1:
        if ox >= x:
            dx = -1
        else:
            dx = 1
        if oy >= y:
            dy = -1
        else:
            dy = 1
        return [dx, dy]

    # 2) Move toward nearest resource if available
    resources = observation.get("resources", [])
    if isinstance(resources, list) and resources:
        best = None
        best_dist = 10**9
        for r in resources:
            rx = int(r.get("x", x))
            ry = int(r.get("y", y))
            d = abs(rx - x) + abs(ry - y)
            if d < best_dist:
                best_dist = d
                best = (rx, ry)
        if best is not None:
            rx, ry = best
            if rx > x:
                dx = 1
            elif rx < x:
                dx = -1
            else:
                dx = 0
            if ry > y:
                dy = 1
            elif ry < y:
                dy = -1
            else:
                dy = 0
            return [dx, dy]

    # 3) Fallback: move in a fixed deterministic pattern within bounds
    if grid_w > 0 and grid_h > 0:
        if (x + y) % 2 == 0:
            if x + 1 < grid_w:
                return [1, 0]
            if y + 1 < grid_h:
                return [0, 1]
            return [-1, 0]
        else:
            if y + 1 < grid_h:
                return [0, 1]
            if x + 1 < grid_w:
                return [1, 0]
            return [0, -1]

    # 4) Default stay if no information
    return [0, 0]
